class _StatusLabel:
    """STATUS_LABEL[k] restituisce l'etichetta tradotta (rispetta la lingua)."""
    _m = {'lotw': 'st_lotw', 'paper': 'st_paper', 'eqsl': 'st_eqsl',
          'work': 'st_work', 'none': 'st_none'}
    def __getitem__(self, k):
        return T(self._m.get(k, k))
STATUS_LABEL = _StatusLabel()
_TEXT = '#e8edf2'; _MUTED = '#95a1ad'; _BG = '#161b21'; _PANEL = '#0d1116'


def _esc(s):
    return (str(s).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;'))


def _legend_svg(x, y, col):
    out = [f'<text x="{x}" y="{y-10}" fill="{_MUTED}" font-size="13">'
           f'{_esc(T("legenda_conferme"))}</text>']
    for key in ('lotw', 'paper', 'eqsl', 'work', 'none'):
        out.append(f'<rect x="{x}" y="{y}" width="20" height="20" rx="4" '
                   f'fill="{col[key]}" stroke="{_PANEL}"/>')
        out.append(f'<text x="{x+26}" y="{y+15}" fill="{_TEXT}" font-size="13">'
                   f'{STATUS_LABEL[key]}</text>')
        x += 34 + 9 * len(STATUS_LABEL[key])
    return "\n".join(out)


def _us_flag(x, y, w=66, h=35):
    """Bandiera USA stilizzata (SVG) per l'angolo delle mappe WAS."""
    RED = '#b22234'; WHT = '#ffffff'; BLU = '#3c3b6e'
    sh = h / 13.0
    cw = w * 0.42; ch = sh * 7
    out = ['<g>']
    out.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{WHT}" '
               f'stroke="#0b0f14" stroke-width="1" rx="2"/>')
    for i in range(0, 13, 2):   # 7 strisce rosse
        out.append(f'<rect x="{x}" y="{y+i*sh:.2f}" width="{w}" height="{sh:.2f}" fill="{RED}"/>')
    out.append(f'<rect x="{x}" y="{y}" width="{cw:.1f}" height="{ch:.1f}" fill="{BLU}"/>')
    for r in range(5):
        for c in range(6):
            sx = x + cw * (c + 1) / 7.0
            sy = y + ch * (r + 1) / 6.0
            out.append(f'<circle cx="{sx:.1f}" cy="{sy:.1f}" r="0.85" fill="{WHT}"/>')
    out.append('</g>')
    return "\n".join(out)


def _render_us_geo(statuses, title, subtitle, names, colors, footer,
                   show_labels=True):
    col = dict(DEFAULT_COLORS); col.update(colors or {})
    names = names or {}
    _, _, VW, VH = US_VIEWBOX
    scale = 1.0
    pad = 26
    top = 96 if title else 20
    legend_h = 70
    foot_h = 26 if footer else 8
    W = VW + pad * 2
    H = top + VH + legend_h + foot_h

    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" '
           f'viewBox="0 0 {W} {H}" font-family="Segoe UI, Arial, sans-serif">']
    out.append(f'<rect width="{W}" height="{H}" rx="14" fill="{_BG}"/>')
    if title:
        out.append(_us_flag(pad, 13, 52, 27))
        out.append(f'<text x="{pad+66}" y="42" fill="{_TEXT}" font-size="27" '
                   f'font-weight="700">{_esc(title)}</text>')
    if subtitle:
        out.append(f'<text x="{pad+66 if title else pad}" y="70" fill="{_MUTED}" font-size="15">'
                   f'{_esc(subtitle)}</text>')

    out.append(f'<g transform="translate({pad},{top})">')
    for st, d in US_PATHS.items():
        stt, nq = statuses.get(st, ('none', 0))
        fill = col.get(stt, col['none'])
        nm = names.get(st) or names.get(st.upper()) or st
        out.append(f'<path d="{d}" fill="{fill}" stroke="{_PANEL}" '
                   f'stroke-width="1"><title>{_esc(nm)} — {STATUS_LABEL[stt]}'
                   f'{f" ({nq} QSO)" if nq else ""}</title></path>')
    if show_labels:
        for st, (ax, ay) in US_ANCHORS.items():
            if st == 'DC':
                continue
            stt, _ = statuses.get(st, ('none', 0))
            tcol = '#0d1a12' if stt in ('lotw', 'paper', 'eqsl') else _TEXT
            out.append(f'<text x="{ax}" y="{ay+3}" fill="{tcol}" font-size="12" '
                       f'font-weight="700" text-anchor="middle" '
                       f'style="paint-order:stroke;stroke:#00000055;'
                       f'stroke-width:2px">{st}</text>')
    out.append('</g>')

    out.append(_legend_svg(pad, top + VH + 30, col))
    if footer:
        out.append(f'<text x="{pad}" y="{H-10}" fill="{_MUTED}" font-size="11">'
                   f'{_esc(footer)}</text>')
    out.append('</svg>')
    return "\n".join(out)


def _render_tiles(kind, statuses, title, subtitle, names, colors, footer,
                  cell=54, gap=6, radius=8, show_qso=True):
    grid = GRIDS[kind]
    col = dict(DEFAULT_COLORS); col.update(colors or {})
    names = names or {}
    rows = max(r for r, _ in grid.values()) + 1
    ncols = max(c for _, c in grid.values()) + 1
    pad = 28; top = 96 if title else pad; legend_h = 70
    W = pad * 2 + ncols * cell + (ncols - 1) * gap
    H = top + rows * cell + (rows - 1) * gap + legend_h + (30 if footer else 12)
    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" '
           f'viewBox="0 0 {W} {H}" font-family="Segoe UI, Arial, sans-serif">']
    out.append(f'<rect width="{W}" height="{H}" rx="14" fill="{_BG}"/>')
    if title:
        out.append(f'<text x="{pad}" y="42" fill="{_TEXT}" font-size="26" '
                   f'font-weight="700">{_esc(title)}</text>')
    if subtitle:
        out.append(f'<text x="{pad}" y="70" fill="{_MUTED}" font-size="15">'
                   f'{_esc(subtitle)}</text>')
    for rid, (r, c) in grid.items():
        st, nq = statuses.get(rid, ('none', 0))
        x = pad + c * (cell + gap); y = top + r * (cell + gap)
        fill = col.get(st, col['none'])
        tcol = _MUTED if st == 'none' else (_TEXT if st == 'work' else '#0d1a12')
        nm = names.get(rid) or names.get(str(rid)) or ''
        out.append('<g>')
        if nm:
            out.append(f'<title>{_esc(nm)} — {STATUS_LABEL[st]}'
                       f'{f" ({nq} QSO)" if nq else ""}</title>')
        out.append(f'<rect x="{x}" y="{y}" width="{cell}" height="{cell}" '
                   f'rx="{radius}" fill="{fill}" stroke="{_PANEL}" stroke-width="2"/>')
        out.append(f'<text x="{x+cell/2:.1f}" y="{y+cell/2+1:.1f}" fill="{tcol}" '
                   f'font-size="{15 if len(str(rid))<=2 else 12}" font-weight="700" '
                   f'text-anchor="middle" dominant-baseline="middle">{_esc(rid)}</text>')
        if show_qso and nq:
            out.append(f'<text x="{x+cell-5:.1f}" y="{y+cell-5:.1f}" fill="{tcol}" '
                       f'font-size="9" text-anchor="end" opacity="0.8">{nq}</text>')
        out.append('</g>')
    out.append(_legend_svg(pad, top + rows * cell + (rows - 1) * gap + 30, col))
    if footer:
        out.append(f'<text x="{pad}" y="{H-12}" fill="{_MUTED}" font-size="11">'
                   f'{_esc(footer)}</text>')
    out.append('</svg>')
    return "\n".join(out)


def _render_cq_geo(statuses, title, subtitle, names, colors, footer,
                   show_labels=True):
    """Mappa mondiale reale delle 40 zone CQ, colorate per stato conferma."""
    col = dict(DEFAULT_COLORS); col.update(colors or {})
    names = names or {}
    xs_all = [x for xs, _ in CQ_ZONES.values() for x in xs]
    ys_all = [y for _, ys in CQ_ZONES.values() for y in ys]
    minx, maxx = min(xs_all), max(xs_all)
    miny, maxy = min(ys_all), max(ys_all)
    MAPW = 1120.0
    scale = MAPW / (maxx - minx)
    MAPH = scale * (maxy - miny)
    pad = 26
    top = 96 if title else 20
    legend_h = 70
    foot_h = 26 if footer else 8
    W = MAPW + pad * 2
    H = top + MAPH + legend_h + foot_h

    def px(lng): return (lng - minx) * scale
    def py(lat): return (maxy - lat) * scale

    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W:.0f}" '
           f'height="{H:.0f}" viewBox="0 0 {W:.0f} {H:.0f}" '
           f'font-family="Segoe UI, Arial, sans-serif">']
    out.append(f'<rect width="{W:.0f}" height="{H:.0f}" rx="14" fill="{_BG}"/>')
    if title:
        out.append(f'<text x="{pad}" y="42" fill="{_TEXT}" font-size="27" '
                   f'font-weight="700">{_esc(title)}</text>')
    if subtitle:
        out.append(f'<text x="{pad}" y="70" fill="{_MUTED}" font-size="15">'
                   f'{_esc(subtitle)}</text>')

    out.append(f'<g transform="translate({pad},{top})">')
    for z in sorted(CQ_ZONES):
        xs, ys = CQ_ZONES[z]
        stt, nq = statuses.get(z, statuses.get(str(z), ('none', 0)))
        fill = col.get(stt, col['none'])
        pts = " ".join(f"{px(x):.1f},{py(y):.1f}" for x, y in zip(xs, ys))
        nm = names.get(z) or names.get(str(z)) or f"Zona {z}"
        out.append(f'<polygon points="{pts}" fill="{fill}" stroke="{_PANEL}" '
                   f'stroke-width="0.8"><title>{_esc(nm)} — {STATUS_LABEL[stt]}'
                   f'{f" ({nq} QSO)" if nq else ""}</title></polygon>')
    # Cartina mondiale stilizzata (coste) in sovraimpressione sulle zone.
    if _COSTE:
        out.append('<defs><clipPath id="cqcoast">'
                   f'<rect x="0" y="0" width="{MAPW:.0f}" height="{MAPH:.0f}"/>'
                   '</clipPath></defs>')
        out.append(f'<g clip-path="url(#cqcoast)" fill="none" stroke="{_TEXT}" '
                   f'stroke-opacity="0.4" stroke-width="0.7" stroke-linejoin="round">')
        for line in _COSTE:
            pts = " ".join(f"{px(x):.1f},{py(y):.1f}" for x, y in line)
            out.append(f'<polyline points="{pts}"/>')
        out.append('</g>')
    if show_labels:
        for z in sorted(CQ_ZONES):
            lng, lat = CQ_LABELS[z]
            stt, _ = statuses.get(z, statuses.get(str(z), ('none', 0)))
            tcol = '#0d1a12' if stt in ('lotw', 'paper', 'eqsl') else _TEXT
            out.append(f'<text x="{px(lng):.1f}" y="{py(lat)+4:.1f}" fill="{tcol}" '
                       f'font-size="13" font-weight="700" text-anchor="middle" '
                       f'style="paint-order:stroke;stroke:#00000066;'
                       f'stroke-width:2.5px">{z}</text>')
    out.append('</g>')

    out.append(_legend_svg(pad, top + MAPH + 30, col))
    if footer:
        out.append(f'<text x="{pad}" y="{H-10:.0f}" fill="{_MUTED}" font-size="11">'
                   f'{_esc(footer)}</text>')
    out.append('</svg>')
    return "\n".join(out)



def _geo_stt(statuses, key):
    """Cerca lo stato provando piu' forme della chiave (str/int/2-cifre)."""
    cands = [key]
    try:
        n = int(key); cands += [n, str(n), f"{n:02d}"]
    except (ValueError, TypeError):
        pass
    for k in cands:
        if k in statuses:
            return statuses[k]
    return ('none', 0)


def _render_waja_geo(statuses, title, subtitle, names, colors, footer,
                     show_labels=True):
    """Mappa reale delle 47 prefetture (WAJA), colorate per stato conferma.
    Chiavi = codici JIS X 0401 ('01'..'47'). Proiezione equirettangolare
    con correzione cos(lat) per proporzioni corrette del Giappone."""
    col = dict(DEFAULT_COLORS); col.update(colors or {})
    nm_map = dict(WAJA_NAMES); nm_map.update(names or {})

    all_x = [x for rings in WAJA_ZONES.values() for xs, _ in rings for x in xs]
    all_y = [y for rings in WAJA_ZONES.values() for _, ys in rings for y in ys]
    miny, maxy = min(all_y), max(all_y)
    kx = math.cos(math.radians((miny + maxy) / 2.0))   # compressione longitudini
    ex = [x * kx for x in all_x]
    minx, maxx = min(ex), max(ex)

    MAPH = 700.0
    scale = MAPH / (maxy - miny)
    MAPW = scale * (maxx - minx)
    pad = 26
    top = 96 if title else 20
    legend_h = 70
    foot_h = 26 if footer else 8
    W = MAPW + pad * 2
    H = top + MAPH + legend_h + foot_h

    def px(lng): return (lng * kx - minx) * scale
    def py(lat): return (maxy - lat) * scale

    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W:.0f}" '
           f'height="{H:.0f}" viewBox="0 0 {W:.0f} {H:.0f}" '
           f'font-family="Segoe UI, Arial, sans-serif">']
    out.append(f'<rect width="{W:.0f}" height="{H:.0f}" rx="14" fill="{_BG}"/>')
    if title:
        out.append(f'<text x="{pad}" y="42" fill="{_TEXT}" font-size="27" '
                   f'font-weight="700">{_esc(title)}</text>')
    if subtitle:
        out.append(f'<text x="{pad}" y="70" fill="{_MUTED}" font-size="15">'
                   f'{_esc(subtitle)}</text>')

    out.append(f'<g transform="translate({pad},{top})">')
    for code in sorted(WAJA_ZONES):
        stt, nq = _geo_stt(statuses, code)
        fill = col.get(stt, col['none'])
        nm = nm_map.get(code) or f"Pref {code}"
        title_el = (f'<title>{_esc(nm)} ({code}) — {STATUS_LABEL[stt]}'
                    f'{f" ({nq} QSO)" if nq else ""}</title>')
        for xs, ys in WAJA_ZONES[code]:
            pts = " ".join(f"{px(x):.1f},{py(y):.1f}" for x, y in zip(xs, ys))
            out.append(f'<polygon points="{pts}" fill="{fill}" stroke="{_PANEL}" '
                       f'stroke-width="0.6">{title_el}</polygon>')
    if show_labels:
        for code in sorted(WAJA_LABELS):
            lng, lat = WAJA_LABELS[code]
            stt, _ = _geo_stt(statuses, code)
            tcol = '#0d1a12' if stt in ('lotw', 'paper', 'eqsl') else _TEXT
            out.append(f'<text x="{px(lng):.1f}" y="{py(lat)+4:.1f}" fill="{tcol}" '
                       f'font-size="11" font-weight="700" text-anchor="middle" '
                       f'style="paint-order:stroke;stroke:#00000088;'
                       f'stroke-width:2.5px">{int(code)}</text>')
    out.append('</g>')

    out.append(_legend_svg(pad, top + MAPH + 30, col))
    if footer:
        out.append(f'<text x="{pad}" y="{H-10:.0f}" fill="{_MUTED}" font-size="11">'
                   f'{_esc(footer)}</text>')
    out.append('</svg>')
    return "\n".join(out)



_WAC_CONT = {
    'NA': ('Nord America', -100, 42), 'SA': ('Sud America', -60, -12),
    'EU': ('Europa', 18, 50), 'AF': ('Africa', 22, 3),
    'AS': ('Asia', 95, 43), 'OC': ('Oceania', 135, -25),
}


def _render_wac_geo(statuses, title, subtitle, names, colors, footer):
    """Mappa WAC: planisfero stilizzato (coste) con i 6 continenti come
    pastiglie colorate per stato conferma."""
    col = dict(DEFAULT_COLORS); col.update(colors or {})
    names = names or {}
    LONMIN, LONMAX, LATMIN, LATMAX = -180.0, 180.0, -58.0, 84.0
    MAPW = 1000.0
    scale = MAPW / (LONMAX - LONMIN)
    MAPH = scale * (LATMAX - LATMIN)
    pad = 26
    top = 96 if title else 20
    legend_h = 70
    foot_h = 26 if footer else 8
    W = MAPW + pad * 2
    H = top + MAPH + legend_h + foot_h

    def px(lng): return (lng - LONMIN) * scale
    def py(lat): return (LATMAX - lat) * scale

    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W:.0f}" '
           f'height="{H:.0f}" viewBox="0 0 {W:.0f} {H:.0f}" '
           f'font-family="Segoe UI, Arial, sans-serif">']
    out.append(f'<rect width="{W:.0f}" height="{H:.0f}" rx="14" fill="{_BG}"/>')
    if title:
        out.append(f'<text x="{pad}" y="42" fill="{_TEXT}" font-size="27" '
                   f'font-weight="700">{_esc(title)}</text>')
    if subtitle:
        out.append(f'<text x="{pad}" y="70" fill="{_MUTED}" font-size="15">'
                   f'{_esc(subtitle)}</text>')

    out.append(f'<g transform="translate({pad},{top})">')
    # Sfondo mare + planisfero (coste)
    out.append(f'<rect x="0" y="0" width="{MAPW:.0f}" height="{MAPH:.0f}" '
               f'rx="10" fill="{_PANEL}"/>')
    if _COSTE:
        out.append(f'<defs><clipPath id="waccoast"><rect x="0" y="0" '
                   f'width="{MAPW:.0f}" height="{MAPH:.0f}"/></clipPath></defs>')
        out.append(f'<g clip-path="url(#waccoast)" fill="none" stroke="{_MUTED}" '
                   f'stroke-opacity="0.55" stroke-width="0.7" stroke-linejoin="round">')
        for line in _COSTE:
            pts = " ".join(f"{px(x):.1f},{py(y):.1f}" for x, y in line)
            out.append(f'<polyline points="{pts}"/>')
        out.append('</g>')
    # Pastiglie continenti
    R = 30
    for code, (nm, lng, lat) in _WAC_CONT.items():
        st, nq = statuses.get(code, statuses.get(str(code), ('none', 0)))
        fill = col.get(st, col['none'])
        tcol = '#0d1a12' if st in ('lotw', 'paper', 'eqsl') else _TEXT
        cx, cy = px(lng), py(lat)
        full = names.get(code) or nm
        out.append(f'<g><title>{_esc(full)} — {STATUS_LABEL[st]}'
                   f'{f" ({nq} QSO)" if nq else ""}</title>')
        out.append(f'<circle cx="{cx:.1f}" cy="{cy:.1f}" r="{R}" fill="{fill}" '
                   f'stroke="{_BG}" stroke-width="3"/>')
        out.append(f'<text x="{cx:.1f}" y="{cy-2:.1f}" fill="{tcol}" font-size="18" '
                   f'font-weight="700" text-anchor="middle" '
                   f'dominant-baseline="middle">{_esc(code)}</text>')
        if nq:
            out.append(f'<text x="{cx:.1f}" y="{cy+14:.1f}" fill="{tcol}" '
                       f'font-size="10" text-anchor="middle" opacity="0.85">'
                       f'{nq}</text>')
        out.append('</g>')
    out.append('</g>')

    out.append(_legend_svg(pad, top + MAPH + 30, col))
    if footer:
        out.append(f'<text x="{pad}" y="{H-10:.0f}" fill="{_MUTED}" font-size="11">'
                   f'{_esc(footer)}</text>')
    out.append('</svg>')
    return "\n".join(out)


def render_svg(kind, statuses, title="", subtitle="", names=None,
               colors=None, footer="", **kw):
    """SVG dell'award `kind`. WAS/WAZ/WAJA/WAC = mappe geografiche reali."""
    if kind in ('WAS', 'WAS250'):
        return _render_us_geo(statuses, title, subtitle, names, colors, footer,
                              show_labels=kw.get('show_labels', True))
    if kind == 'WAZ':
        return _render_cq_geo(statuses, title, subtitle, names, colors, footer,
                              show_labels=kw.get('show_labels', True))
    if kind == 'WAJA':
        return _render_waja_geo(statuses, title, subtitle, names, colors, footer,
                                show_labels=kw.get('show_labels', True))
    if kind == 'WAC':
        return _render_wac_geo(statuses, title, subtitle, names, colors, footer)
    return _render_tiles(kind, statuses, title, subtitle, names, colors, footer,
                         cell=kw.get('cell', 54))


def statuses_from_model(model, strict, any_cell, cell_status, newcell,
                        group='mixed', band=None):
    """Stato per entità per lo slice richiesto.
    group: 'mixed'|'phone'|'cw'|'digital' (modo). band: None/'Tutte' = tutte le
    bande, altrimenti solo quella banda (es. '17m'). Così la mappa può mostrare
    una fetta specifica (es. 17m SSB) invece del solo aggregato mixed.
    Per group='sat' si usano i satelliti (model['sat']/'sat_names') e 'band'
    seleziona un singolo satellite."""
    if group == 'sat':
        data = model.get('sat', {})
        cols = model.get('sat_names', [])
        sel = [band] if (band and band in cols) else cols
        out = {}
        for rid, _label in model['rows']:
            cc = any_cell([(data.get(rid, {}).get(c) or newcell()) for c in sel])
            out[rid] = (cell_status(cc, strict), cc['w'])
        return out
    data = model['data'].get(group) or model['data']['mixed']
    bands = [band] if (band and band in model['bands']) else model['bands']
    out = {}
    for rid, _label in model['rows']:
        cc = any_cell([(data[rid].get(b) or newcell()) for b in bands])
        out[rid] = (cell_status(cc, strict), cc['w'])
    return out
